UPDATE asset
asset_owner_id = #{assetOwnerId}, asset_name = #{assetName}, asset_type = #{assetType}, asset_due_time = #{assetDueTime}, asset_status = #{assetStatus}, asset_area = #{assetArea}, asset_building = #{assetBuilding}, asset_floor = #{assetFloor}, asset_position = #{assetPosition}, asset_remark = #{assetRemark},
WHERE id = #{id}

mapper.select:
SELECT a.*, u.user_name AS owner_name, at2.asset_type_name, at2.asset_type_short, b.building_code, b.building_name, b.building_min_floor, b.building_max_floor, b.building_location FROM asset a LEFT JOIN user u ON a.asset_owner_id = u.id LEFT JOIN asset_type at2 ON a.asset_type = at2.asset_type_id LEFT JOIN building b ON a.asset_building = b.id
AND a.asset_owner_id = #{assetOwnerId}
AND u.uid LIKE CONCAT('%', #{ownerUid}, '%')
AND a.asset_type = #{assetType}
AND a.asset_status = #{assetStatus}
AND a.asset_building = #{assetBuilding}
ORDER BY a.id ASC

SELECT a.*, u.user_name AS owner_name, at2.asset_type_name, at2.asset_type_short, b.building_code, b.building_name, b.building_min_floor, b.building_max_floor, b.building_location FROM asset a LEFT JOIN user u ON a.asset_owner_id = u.id LEFT JOIN asset_type at2 ON a.asset_type = at2.asset_type_id LEFT JOIN building b ON a.asset_building = b.id
AND a.asset_owner_id = #{assetOwnerId}
ORDER BY a.id ASC
